import { onMount } from 'solid-js';
import { dropTarget } from '../drag/drag-gesture.js';
import type { Term } from '../../../model-boundary.js';

export function zoneOnHeader(
  el: HTMLElement | null, sel: string, kind: string, term: Term | null,
): void {
  if (!el || !term) return;
  // A `ref` callback fires before the element is in the tree, so `closest()`
  // would return null and no zone would register at all.
  onMount(() => {
    const header = el.closest(sel) as HTMLElement | null;
    if (header) dropTarget(header, kind, term);
  });
}
