const OBLIGATION = `${ODRL}obligation`;

function runAndReveal(core: Core, fn: (f: unknown) => unknown): void {
  let fresh: unknown = null;
  void core.execute((f) => { fresh = fn(f); }, { group: true })
    .then((ok) => {
      const ref = termOf(fresh)?.value;
      if (!ok) return;
      if (ref) core.jump(ref);
      requestFocusOn(fresh);
    })
    .catch(() => {});
}

export function requestFocusOn(fresh: unknown): void {
  const t = termOf(fresh) as { id?: string; value?: string } | null;
  const address = focusAddress(t ?? fresh);
  if (address) requestEditFocus(address);
}

function cardClearQuads(core: Core, t0: unknown) {
  const g = core.graph();
  return (g && t0) ? core.edit.policyClearQuads(g, t0) : [];
}

export function CardHeaderStrip(props: { core: Core; ctx: CardHookCtx }): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const derived = (): IconState => ({ on: false, title: text('edit.cardDerived') });
  const clearQuads = createMemo(() => cardClearQuads(props.core, term()));
  return (
    <Show
      when={term()}
      fallback={(
        <ActionStrip
          drag={{ on: false, title: text('edit.dragCardNa') }}
          edit={props.ctx.titleEdit
            ? { on: false, title: text('edit.nameDerived') } : undefined}
          duplicate={derived()}
          remove={derived()}
        />
      )}
    >{(t0) => (
      <ActionStrip
        label={text('edit.stripLabel')}
        ref={(el) => zoneOnHeader(el, 'summary', DROPTARGET.CARD, t0())}
        drag={{ on: false, title: text('edit.dragCardNa') }}
        edit={props.ctx.titleEdit as IconState | undefined}
        duplicate={props.ctx.pol.anon || !props.ctx.pol.iri
          ? { on: false, title: text('edit.duplicateNoIri') }
          : editState(props.core, {
            allow: props.core.editable(t0()),
            title: text('edit.duplicateHint'),
            action: () => runAndReveal(props.core,
              (f) => props.core.edit.duplicatePolicy(f, props.ctx.pol.iri)),
            term: t0(),
            unlockable: true,
          })}
        remove={editState(props.core, {
          allow: clearQuads().length > 0 && props.core.quadsInEditSource(clearQuads()),
          title: text('edit.removePolicy'),
          action: () => {
            void props.core.execute((f) => props.core.edit.removePolicy(f, t0()),
              { group: true })
              .then((ok) => { if (ok) showToast('edit.policyRemoved'); })
              .catch(() => {});
          },
          term: t0(),
          blocked: clearQuads(),
          unlockable: true,
        })}
      />
    )}</Show>
  );
}

const ATTACH_PRED: Record<string, string> = {
  permission: `${ODRL}permission`,
  prohibition: `${ODRL}prohibition`,
  duty: OBLIGATION,
};

let ruleCache: { g: unknown; v: number; per: Record<string, {
  iri: string; curie: string | null; label: string; provenance: string[];
}[]> } | null = null;

function reuseOptions(core: Core, term: unknown, kind: string): IriOption[] {
  const g = core.graph();
  const v = graphVersion();
  if (!g || !term) return [];
  if (!ruleCache || ruleCache.g !== g || ruleCache.v !== v) {
    ruleCache = { g, v, per: core.edit.ruleOptions(g) };
  }
  const pred = ATTACH_PRED[kind];
  return asIriOptions((ruleCache.per[kind] || [])
    .filter((r) => core.edit.attachCheck(g, term, pred, r.iri).ok));
}

function RuleReuseRow(props: {
  core: Core; term: unknown; kind: string; onClose: () => void;
}): JSX.Element {
  const options = createMemo(() => reuseOptions(props.core, props.term, props.kind));
  const pick = (iri: string): void => {
    const pred = ATTACH_PRED[props.kind];
    const verdict = props.core.edit.attachCheck(props.core.graph(), props.term, pred, iri);
    if (!verdict.ok) {
      setNotice(RULE_NOTICE[verdict.reason || ''] || 'edit.invalidIri', { input: iri });
      return;
    }
    let fresh: unknown = null;
    void props.core.execute((f) => {
      fresh = props.core.edit.attachRule(f, props.term, pred, iri).term;
    }, { group: true })
      .then((ok) => {
        if (!ok) return;
        showToast('edit.ruleAttached');
        props.onClose();
        requestFocusOn(fresh);
      })
      .catch(() => {});
  };
  return (
    <ReuseRow
      options={options()}
      chooseKey="edit.reuseChoose"
      onPick={pick}
      onClose={props.onClose}
    />
  );
}

export function CardRuleGhost(props: { core: Core; ctx: CardHookCtx }): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const [reuseOpen, setReuseOpen] = createSignal<string | null>(null);
  const option = (
    kind: 'permission' | 'prohibition' | 'duty', wordKey: string,
    titleKey: string, cls: string, mut: (f: unknown, t0: unknown) => unknown,
  ): GhostOption => {
    const t0 = term();
    const state = editState(props.core, {
      allow: props.core.editable(t0),
      title: text(titleKey),
      action: () => {
        let fresh: unknown = null;
        void props.core.execute((f) => { fresh = mut(f, t0); }, { group: true })
          .then((ok) => { if (ok) requestFocusOn(fresh); })
          .catch(() => {});
      },
      term: t0,
      unlockable: true,
    });
    return {
      node: <GhostBadge kind={kind} word={text(wordKey)} />,
      cls,
      title: state.title,
      on: state.on,
      action: state.action,
    };
  };
  const shows = (s: 'permission' | 'prohibition' | 'duty'): boolean =>
    !props.ctx.kinds || props.ctx.kinds.includes(s);
  const reuseOption = (kind: 'permission' | 'prohibition' | 'duty',
    cls: string): GhostOption => {
    const t0 = term();
    return reuseSegment({
      core: props.core,
      term: t0,
      cls,
      count: reuseOptions(props.core, t0, kind).length,
      hint: 'edit.reuseHint',
      none: 'edit.reuseNone',
      toggle: () => setReuseOpen(reuseOpen() === kind ? null : kind),
    });
  };
  const rowCls = () => (props.ctx.placement === 'section'
    ? 'ghost-op-row ghost-section-row' : 'ghost-op-row');
  return (
    <Show when={term()}>
      <GhostWithBox
        cls={rowCls()}
        options={[
          shows('permission') && option('permission', 'edit.permission',
            'edit.addPermission', 'card-permission-plus',
            (f, t0) => props.core.edit.addPermission(f, t0)),
          shows('permission') && reuseOption('permission', 'card-permission-reuse'),
          shows('prohibition') && option('prohibition', 'edit.prohibition', 'edit.addProhibition',
            'card-prohibition-plus',
            (f, t0) => props.core.edit.addProhibition(f, t0)),
          shows('prohibition') && reuseOption('prohibition', 'card-prohibition-reuse'),
          shows('duty') && option('duty', 'edit.duty', 'edit.addDuty',
            'card-duty-plus',
            (f, t0) => props.core.edit.addDuty(f, t0, OBLIGATION)),
          shows('duty') && reuseOption('duty', 'card-duty-reuse'),
        ].filter(Boolean) as GhostOption[]}
      />
      <Show when={reuseOpen()}>{(kind) => (
        <RuleReuseRow
          core={props.core}
          term={term()}
          kind={kind()}
          onClose={() => setReuseOpen(null)}
        />
      )}</Show>
    </Show>
  );
}

const PURPOSE = `${ODRL}purpose`;

export function GroupRuleGhost(props: { core: Core; ctx: GroupHookCtx }): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const kind = () => (props.ctx.kind === 'prohibition' ? 'prohibition' : 'permission');
  const prefillable = () => props.ctx.dimIri === PURPOSE && !!props.ctx.valueIri;
  const option = (): GhostOption => {
    const t0 = term();
    const value = props.ctx.valueLabel || props.ctx.valueIri || '';
    if (!prefillable()) {
      return {
        node: <GhostBadge kind={kind()} word={text(ADD_RULE_KEY[kind()])} />,
        cls: `group-${kind()}-plus`,
        title: text('edit.dimensionNoPrefill'),
        on: false,
      };
    }
    const state = editState(props.core, {
      allow: props.core.editable(t0),
      title: text('edit.addInDimension', { value }),
      action: () => {
        const opts = { purposeIri: props.ctx.valueIri as string };
        let fresh: unknown = null;
        void props.core.execute((f) => {
          fresh = kind() === 'prohibition'
            ? props.core.edit.addProhibition(f, t0, opts)
            : props.core.edit.addPermission(f, t0, opts);
        }, { group: true })
          .then((ok) => { if (ok) requestFocusOn(fresh); })
          .catch(() => {});
      },
      term: t0,
      unlockable: true,
    });
    return {
      node: <GhostBadge kind={kind()} word={text(ADD_RULE_KEY[kind()])} />,
      cls: `group-${kind()}-plus`,
      title: state.title,
      on: state.on,
      action: state.action,
    };
  };
  return (
    <Show when={term()}>
      <GhostWithBox cls="ghost-op-row" options={[option()]} />
    </Show>
  );
}

const ADD_HINT_KEY: Record<AddKind, string> = {
  offer: 'edit.newPolicyHint',
  agreement: 'edit.newAgreementHint',
  request: 'edit.newRequestHint',
  set: 'edit.newSetHint',
};

const ADD_WORD_KEY: Record<AddKind, string> = {
  offer: 'kind.offer',
  agreement: 'kind.agreement',
  request: 'kind.request',
  set: 'kind.set',
};

// The + of a section header: the same control in all four categories, so the
// kind only travels as an argument into the one minting flow.
export function NewPolicyGhost(props: { core: Core; ctx: AddHookCtx }): JSX.Element {
  const kind = (): AddKind => props.ctx.kind || 'offer';
  const state = createMemo(() => editState(props.core, {
    allow: props.core.hasEditSource(),
    title: text(ADD_HINT_KEY[kind()]),
    // The fresh policy is blank, so the reveal travels as the TERM: a blank
    // node has no IRI to jump to, only its node id.
    action: () => runAndReveal(props.core,
      (f) => props.core.edit.createSkeleton(f, kind()).term),
    unlockable: true,
  }));
  const locked = () => !state().on && !!state().action;
  return (
    <span class="new-policy">
      <button
        type="button"
        class={'new-policy-button sec-add-btn sec-add-' + kind()
          + (state().on ? '' : (locked() ? ' locked' : ' action-off'))}
        title={state().title}
        aria-label={text('edit.addAria', { kind: text(ADD_WORD_KEY[kind()]) })}
        aria-disabled={state().on || locked() ? undefined : 'true'}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          state().action?.(e);
        }}
        onPointerDown={(e) => e.stopPropagation()}
      >
                <svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true">
          <path d="M7.25 2.5h1.5v4.75H13.5v1.5H8.75V13.5h-1.5V8.75H2.5v-1.5h4.75z" fill="currentColor" />
        </svg>
        <Show when={locked()}><SlotIcon /></Show>
      </button>
    </span>
  );
}

